'use strict';

/**
* Test whether every element in a single-precision floating-point strided array is falsy.
*
* @module @stdlib/blas/ext/base/snone
*
* @example
* import Float32Array from '@stdlib/array/float32';
* import snone from '@stdlib/blas/ext/base/snone';
*
* var x = new Float32Array( [ 0.0, 0.0, 1.0, 1.0 ] );
*
* var v = snone( x.length, x, 1 );
* // returns false
*
* @example
* import Float32Array from '@stdlib/array/float32';
* import snone from '@stdlib/blas/ext/base/snone';
*
* var x = new Float32Array( [ 0.0, 0.0, 1.0, 1.0 ] );
*
* var v = snone.ndarray( x.length, x, 1, 0 );
* // returns false
*/

// MODULES //

var join = require( 'path' ).join;
import tryRequire from '@stdlib/utils/try-require';
import isError from '@stdlib/assert/is-error';
import main from './main.js';


// MAIN //

var snone;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	snone = main;
} else {
	snone = tmp;
}


// EXPORTS //

export default snone;

// exports: { "ndarray": "snone.ndarray" }
