'use strict';

/**
* Test whether a double-precision floating-point strided array contains at least `k` truthy elements.
*
* @module @stdlib/blas/ext/base/dsome
*
* @example
* import Float64Array from '@stdlib/array/float64';
* import dsome from '@stdlib/blas/ext/base/dsome';
*
* var x = new Float64Array( [ 0.0, 0.0, 1.0, 2.0 ] );
*
* var v = dsome( x.length, 2, x, 1 );
* // returns true
*
* @example
* import Float64Array from '@stdlib/array/float64';
* import dsome from '@stdlib/blas/ext/base/dsome';
*
* var x = new Float64Array( [ 0.0, 0.0, 1.0, 2.0 ] );
*
* var v = dsome.ndarray( x.length, 2, x, 1, 0 );
* // returns true
*/

// MODULES //

var join = require( 'path' ).join;
import tryRequire from '@stdlib/utils/try-require';
import isError from '@stdlib/assert/is-error';
import main from './main.js';


// MAIN //

var dsome;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dsome = main;
} else {
	dsome = tmp;
}


// EXPORTS //

export default dsome;

// exports: { "ndarray": "dsome.ndarray" }
