'use strict';

/**
* Convert a double-precision floating-point strided array to a min-heap.
*
* @module @stdlib/blas/ext/base/dminheapify
*
* @example
* import Float64Array from '@stdlib/array/float64';
* import dminheapify from '@stdlib/blas/ext/base/dminheapify';
*
* var x = new Float64Array( [ 7.0, 5.0, 3.0, 1.0, 9.0 ] );
*
* dminheapify( 5, x, 1 );
* // x => <Float64Array>[ 1.0, 5.0, 3.0, 7.0, 9.0 ]
*
* @example
* import Float64Array from '@stdlib/array/float64';
* import dminheapify from '@stdlib/blas/ext/base/dminheapify';
*
* var x = new Float64Array( [ 7.0, 5.0, 3.0, 1.0, 9.0 ] );
*
* dminheapify.ndarray( 5, x, 1, 0 );
* // x => <Float64Array>[ 1.0, 5.0, 3.0, 7.0, 9.0 ]
*/

// MODULES //

var join = require( 'path' ).join;
import tryRequire from '@stdlib/utils/try-require';
import isError from '@stdlib/assert/is-error';
import main from './main.js';


// MAIN //

var dminheapify;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dminheapify = main;
} else {
	dminheapify = tmp;
}


// EXPORTS //

export default dminheapify;

// exports: { "ndarray": "dminheapify.ndarray" }
