'use strict';

/**
* Compute the sum of all elements in a one-dimensional double-precision complex floating-point ndarray.
*
* @module @stdlib/blas/ext/base/ndarray/zsum
*
* @example
* import Complex128Vector from '@stdlib/ndarray/vector/complex128';
* import zsum from '@stdlib/blas/ext/base/ndarray/zsum';
*
* var x = new Complex128Vector( [ 1.0, 3.0, 4.0, 2.0 ] );
*
* var v = zsum( [ x ] );
* // returns <Complex128>[ 5.0, 5.0 ]
*/

// MODULES //

var join = require( 'path' ).join;
import tryRequire from '@stdlib/utils/try-require';
import isError from '@stdlib/assert/is-error';
import main from './main.js';


// MAIN //

var zsum;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	zsum = main;
} else {
	zsum = tmp;
}


// EXPORTS //

export default zsum;
