'use strict';

/**
* Compute the sum of all elements in a one-dimensional single-precision complex floating-point ndarray.
*
* @module @stdlib/blas/ext/base/ndarray/csum
*
* @example
* import Complex64Vector from '@stdlib/ndarray/vector/complex64';
* import csum from '@stdlib/blas/ext/base/ndarray/csum';
*
* var x = new Complex64Vector( [ 1.0, 3.0, 4.0, 2.0 ] );
*
* var v = csum( [ x ] );
* // returns <Complex64>[ 5.0, 5.0 ]
*/

// MODULES //

var join = require( 'path' ).join;
import tryRequire from '@stdlib/utils/try-require';
import isError from '@stdlib/assert/is-error';
import main from './main.js';


// MAIN //

var csum;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	csum = main;
} else {
	csum = tmp;
}


// EXPORTS //

export default csum;
